        this.addAnnotation((ENamedElement)this.physicalDimensionEClass, source, new String[]{"documentation", "This class represents a physical dimension.\r\nIf the physical dimension of two units is identical, then a conversion between them is possible. The conversion between units is related to the definition of the physical dimension.\r\n\r\nNote that the equivalence of the exponents does not per se define the convertibility. For example Energy and Torque share the same exponents (Nm).\r\n\r\nPlease note further the the value of an exponent does not necessarily have to be an integer number. It is also possible that the value yields a rational number, e.g. to compute the square root of a given physical quantity. In this case the exponent value would be a rational number where the numerator value is 1 and the denominator value is 2.\r\n\r\n"});
        this.addAnnotation((ENamedElement)this.physicalDimensionEClass.getEOperations().get(0), source, new String[]{"body", "return org.eclipse.sphinx.platform.util.RadixConverter.parseFloat(getLengthExp());"});
        this.addAnnotation((ENamedElement)this.physicalDimensionEClass.getEOperations().get(1), source, new String[]{"body", "return org.eclipse.sphinx.platform.util.RadixConverter.parseInt(getLengthExp());"});
